function renderWork(topic) {
  const work=workTopics[topic];
  const deliverables=topic==='deliverables';
  if(!work&&!deliverables){$('#main').innerHTML=empty('Page not found','Explore our work from the menu.','<a class="button" href="#projects">Browse projects</a>');return;}
  const title=deliverables?'Our deliverables':work.title;
  const intro=deliverables?'Practical outputs that help local teams develop their priorities, communicate project opportunities and engage the right partners.':work.intro;
  $('#main').innerHTML=`<article class="work-page"><div class="crumbs"><a href="#projects">Projects</a>${icon('chevron-right')}<span>${deliverables?'Our deliverables':'Our work'}</span></div><p class="eyebrow">CAPACITY + STRATEGY + PROJECTS</p><h1>${title}</h1><p class="work-intro">${intro}</p>${deliverables?`
    <section class="work-section"><h2>Capacity & learning</h2><div><ul><li>Curricula, learning resources and training programmes.</li><li>Facilitated games, simulations, scenarios and community learning.</li><li>Shared knowledge and experience that local teams can reuse.</li></ul><p class="method-output"><strong>How we develop these</strong>Identify the learning need with participants, turn local situations into stories and role-based exercises, facilitate practice and debriefs, then refine the materials through feedback.</p><a class="text-button method-link" href="#work/training">Our capacity-building methods</a></div></section>
    <section class="work-section"><h2>Strategy & concepts</h2><div><ul><li>Local diagnoses, stakeholder maps and priority plans.</li><li>Scenario comparisons and indicative financial assumptions.</li><li>Concept notes and nine-field project profiles.</li></ul><p class="method-output"><strong>How we develop these</strong>Combine participatory mapping and local accounts with planning games and scenario comparisons. Document the priorities agreed by the local team, develop the profile together and record the evidence still needed.</p><a class="text-button method-link" href="#work/strategy">Our strategy-development methods</a></div></section>
    <section class="work-section"><h2>Partnerships & pitches</h2><div><ul><li>Skills requirements and partner briefs.</li><li>Local contribution statements and preparation-funding asks.</li><li>Project pitches with clear next steps for interested partners.</li></ul><p class="method-output"><strong>How we develop these</strong>Use project clinics to define the partner ask, storytelling to communicate the opportunity, and pitch simulations to rehearse questions. Record feedback and follow-up responsibilities after partner discussions.</p><a class="text-button method-link" href="#work/finance">Our pitch-preparation methods</a></div></section>
  `:`<section class="work-section"><h2>Methods we use</h2><dl class="practice-methods">${work.methods.map(([name,description])=>`<div><dt>${name}</dt><dd>${description}</dd></div>`).join('')}</dl></section><section class="work-section"><h2>How we do it</h2><ol class="practice-steps">${work.steps.map(([name,description])=>`<li><h3>${name}</h3><p>${description}</p></li>`).join('')}</ol></section><section class="work-section"><h2>Who takes part</h2><p>${work.participants}</p></section><section class="work-section"><h2>What you take forward</h2><div><ul>${work.outputs.map(x=>`<li>${x}</li>`).join('')}</ul>${work.note?`<p class="scope-note">${work.note}</p>`:''}</div></section>`}<section class="work-section"><h2>Specialist partners</h2><p>We connect local teams with the expertise needed for the next stage. We do not provide technical assistance, feasibility studies or DPRs, and we do not design or build infrastructure. Qualified external specialists and implementation partners undertake that work.</p></section><div class="actions"><a class="button primary" href="#projects">${icon('layout-grid')}Explore projects</a>${deliverables?'':'<a class="button" href="#deliverables">View all deliverables</a>'}</div></article>`;
  syncIcons();
}
function closeWorkMenu(){if($('#work-menu').open)$('#work-menu').close();}
$('#menu-toggle').addEventListener('click',()=>{$('#work-menu').showModal();$('#menu-toggle').setAttribute('aria-expanded','true');});
$('#close-menu').addEventListener('click',closeWorkMenu);
$('#work-menu').addEventListener('close',()=>$('#menu-toggle').setAttribute('aria-expanded','false'));
$('#work-menu').addEventListener('click',event=>{
  const link=event.target.closest('a');
  if(link){closeWorkMenu();if(link.hash===(location.hash||'#projects'))$('#menu-toggle').focus();return;}
  if(event.target!==$('#work-menu'))return;
  const r=event.target.getBoundingClientRect();
  if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeWorkMenu();
});
function reset() {filters={query:'',state:'All',district:'All',village:'All',sector:'All',need:'All',sort:'featured'};$('#search').value='';renderCatalog(location.hash==='#saved');}
function openOffer(id,kind) {offerProjectId=id;const p=projects.find(p=>p.id===id);$('#offer-form').reset();$('#offer-title').textContent=kind==='Product or solution'?'Propose a solution':kind==='Experience or project example'?'Share an experience':'Offer support';$('#offer-project').textContent=p.title;if(kind)$('#offer-form').elements.kind.value=kind;$('#offer-dialog').showModal();}
document.addEventListener('click',event=>{
  const b=event.target.closest('button');if(!b)return;
  if(b.dataset.save){const id=b.dataset.save;local.saved=local.saved.includes(id)?local.saved.filter(x=>x!==id):[...local.saved,id];const ok=persist();if(location.hash==='#saved')renderResults();else{const p=projects.find(p=>p.id===id);b.outerHTML=saveButton(p);syncSaved();syncIcons();document.querySelector(`[data-save="${id}"]`)?.focus({preventScroll:true});}if(ok)notify(local.saved.includes(id)?'Project saved':'Project removed from saved');}
  if(b.hasAttribute('data-reset'))reset();
  if(b.dataset.sector){filters.sector=b.dataset.sector;document.querySelectorAll('[data-sector]').forEach(x=>{const active=x.dataset.sector===filters.sector;x.classList.toggle('active',active);x.setAttribute('aria-pressed',active);});renderResults();}
  if(b.hasAttribute('data-palwal')||b.dataset.place){filters.state=b.dataset.place||'Haryana';filters.district=b.dataset.place?'All':'Palwal';filters.village='All';filters.query='';filters.sector='All';filters.need='All';$('#search').value='';if(location.hash==='#projects')renderCatalog();else location.hash='#projects';}
  if(b.id==='filter-toggle'){const open=$('#filters').classList.toggle('open');b.setAttribute('aria-expanded',open);}
  if(b.dataset.offer)openOffer(b.dataset.offer);
  if(b.dataset.solution)openOffer(b.dataset.solution,'Product or solution');
  if(b.dataset.experience)openOffer(b.dataset.experience,'Community facilitation');
  if(b.id==='close-offer')$('#offer-dialog').close();
  if(b.dataset.download){const d=local.drafts.find(d=>d.id===b.dataset.download);const text=`${d.title}\n${d.village}, ${d.district}, ${d.state}\nOwner: ${d.owner}\nLOCAL DEMONSTRATION DRAFT - NOT PUBLISHED OR VERIFIED\n\n${fields.map(([k,l],i)=>`${i+1}. ${l}\n${d[k]||'Not yet provided'}\n`).join('\n')}`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='green-gram-project-draft.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
});
document.addEventListener('change',event=>{const k=event.target.dataset.filter;if(!k)return;filters[k]=event.target.value;if(k==='state'){filters.district='All';filters.village='All';}if(k==='district')filters.village='All';if(k==='state'||k==='district'){const wasOpen=$('#filters').classList.contains('open');$('#filters').outerHTML=filterPanel();if(wasOpen)$('#filters').classList.add('open');$(`[data-filter="${k}"]`).focus({preventScroll:true});}renderResults();});
$('#search').addEventListener('input',event=>{filters.query=event.target.value;if($('#project-grid'))renderResults();else location.hash='#projects';});
document.addEventListener('submit',event=>{if(event.target.id==='draft-form'){event.preventDefault();const form=event.target;const data=Object.fromEntries(new FormData(form));for(const k in data)data[k]=data[k].trim();if(!data.title||!data.problem){notify('Add a project name and local problem.');return;}const id=form.dataset.id||`draft-${Date.now()}`;local.drafts=local.drafts.filter(d=>d.id!==id);local.drafts.push({...data,id});const ok=persist();location.hash='#workspace';if(ok)notify('Draft saved in this browser');}if(event.target.id==='offer-form'){event.preventDefault();const data=Object.fromEntries(new FormData(event.target));if(!data.organisation.trim()||!data.message.trim()){notify('Add your organisation and proposal.');return;}local.offers.push({...data,project:offerProjectId,id:`offer-${Date.now()}`});const ok=persist();$('#offer-dialog').close();const p=projects.find(p=>p.id===offerProjectId);renderDetail(p);if(ok)notify('Demo offer recorded locally. No message sent.');}});
$('#offer-dialog').addEventListener('click',event=>{if(event.target!==$('#offer-dialog'))return;const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)event.target.close();});
